def make_q(num, text, oA, oB, oC, oD, ans, exp, topic, sub, diff="Medium"):
    return {
        "q_num": num,
        "q": text,
        "opts": {"A": oA, "B": oB, "C": oC, "D": oD},
        "ans": ans,
        "exp": exp,
        "topic": topic,
        "sub": sub,
        "diff": diff,
        "qtype": "Single Correct MCQ"
    }

